-- P1.8 Enterprise HQ live operations center.
create or replace function public.p1_8_live_operations(p_enterprise_id uuid,p_restaurant_id uuid default null,p_recent_limit integer default 25)
returns jsonb language plpgsql security definer set search_path=public as $$
declare r jsonb; v_limit integer := least(greatest(coalesce(p_recent_limit,25),5),100);
begin
 if not exists(select 1 from public.enterprise_members where enterprise_id=p_enterprise_id and user_id=auth.uid() and role in ('owner','enterprise_admin','operations','finance','inventory_manager','menu_manager')) then raise exception 'Enterprise HQ access denied'; end if;
 if p_restaurant_id is not null and not exists(select 1 from public.enterprise_outlets where enterprise_id=p_enterprise_id and restaurant_id=p_restaurant_id and is_active) then raise exception 'Outlet is not part of this enterprise'; end if;
 select jsonb_build_object('as_of',now(),'outlets',coalesce((select jsonb_agg(q order by q->>'outlet_name') from (select jsonb_build_object('restaurant_id',o.restaurant_id,'outlet_code',o.outlet_code,'outlet_name',coalesce(o.outlet_name,r.name),'is_main_branch',coalesce(o.is_main_branch,false),'status',coalesce(r.status,'active'),'sales_today',coalesce((select sum(x.total_amount) from orders x where x.restaurant_id=o.restaurant_id and x.created_at::date=current_date and lower(coalesce(x.status,'')) not in ('cancelled','canceled','void','voided')),0),'orders_today',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and x.created_at::date=current_date and lower(coalesce(x.status,'')) not in ('cancelled','canceled','void','voided')),0),'bills_today',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and (x.billed_at::date=current_date or (x.invoice_no is not null and x.created_at::date=current_date)) and lower(coalesce(x.status,'')) not in ('cancelled','canceled','void','voided')),0),'running_orders',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and lower(coalesce(x.status,'')) not in ('done','completed','complete','paid','cancelled','canceled','void','voided','closed','settled')),0),'running_tables',coalesce((select count(*) from tables t where t.restaurant_id=o.restaurant_id and lower(coalesce(t.status,'')) in ('occupied','running','busy','reserved')),0),'kot_running',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and lower(coalesce(x.status,'')) in ('pending','confirmed','accepted','preparing','cooking','in_kitchen','kot','sent_to_kitchen')),0),'kitchen_pending',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and lower(coalesce(x.status,'')) in ('pending','confirmed','accepted','preparing','cooking','in_kitchen','kot','sent_to_kitchen')),0),'bills_pending',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and x.billed_at is null and lower(coalesce(x.status,'')) not in ('cancelled','canceled','void','voided','paid','closed','settled')),0),'payment_pending',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and x.billed_at is not null and lower(coalesce(x.payment_status,'')) not in ('paid','settled','completed')),0),'cancelled_today',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and x.created_at::date=current_date and lower(coalesce(x.status,'')) in ('cancelled','canceled','void','voided')),0),'refund_orders_today',coalesce((select count(*) from orders x where x.restaurant_id=o.restaurant_id and x.created_at::date=current_date and lower(coalesce(x.status,'')) in ('refunded','refund')),0),'inventory_items',coalesce((select count(*) from inventory i where i.restaurant_id=o.restaurant_id),0),'low_stock_items',coalesce((select count(*) from inventory i where i.restaurant_id=o.restaurant_id and i.quantity <= coalesce(nullif(i.reorder_level,0),i.min_stock,0)),0),'purchase_orders_today',coalesce((select count(*) from purchase_orders p where p.restaurant_id=o.restaurant_id and p.created_at::date=current_date),0),'purchase_value_today',coalesce((select sum(p.total) from purchase_orders p where p.restaurant_id=o.restaurant_id and p.created_at::date=current_date),0),'customers',coalesce((select count(*) from customers c where c.restaurant_id=o.restaurant_id),0),'staff',coalesce((select count(*) from profiles p where p.restaurant_id=o.restaurant_id),0),'staff_active_today',coalesce((select count(distinct x.waiter_id) from orders x where x.restaurant_id=o.restaurant_id and x.created_at::date=current_date and x.waiter_id is not null),0)) q from enterprise_outlets o join restaurants r on r.id=o.restaurant_id where o.enterprise_id=p_enterprise_id and o.is_active and (p_restaurant_id is null or o.restaurant_id=p_restaurant_id)) q),'[]'::jsonb),'recent_orders',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (select x.id,x.restaurant_id,o.outlet_name,o.outlet_code,o.is_main_branch,x.order_number,x.invoice_no,x.status,x.payment_status,x.payment_method,x.total_amount,x.paid_amount,x.created_at,x.billed_at,x.order_mode,x.table_id,t.table_number,x.customer_name,x.customer_phone from orders x join enterprise_outlets o on o.restaurant_id=x.restaurant_id and o.enterprise_id=p_enterprise_id and o.is_active left join tables t on t.id=x.table_id and t.restaurant_id=x.restaurant_id where (p_restaurant_id is null or x.restaurant_id=p_restaurant_id) order by x.created_at desc limit v_limit) q),'[]'::jsonb),'selected_outlet',case when p_restaurant_id is null then null else (select to_jsonb(o) from enterprise_outlets o where o.enterprise_id=p_enterprise_id and o.restaurant_id=p_restaurant_id and o.is_active limit 1) end) into r; return r;
end $$;
revoke all on function public.p1_8_live_operations(uuid,uuid,integer) from public;
grant execute on function public.p1_8_live_operations(uuid,uuid,integer) to authenticated,service_role;
